class Form_Relay_Admin {
	private $service;
	private $submissions;
	public function __construct( $service, $submissions ) { $this->service = $service; $this->submissions = $submissions; }
	public function hooks() { add_action( 'admin_menu', array( $this, 'menu' ) ); add_action( 'admin_init', array( $this, 'actions' ) ); add_action( 'admin_enqueue_scripts', array( $this, 'assets' ) ); }
	public function menu() { add_menu_page( 'Developer Form Relay', 'Form Relay', 'manage_options', 'form-relay', array( $this, 'page' ), 'dashicons-email-alt' ); add_submenu_page( 'form-relay', 'Forms', 'Forms', 'manage_options', 'form-relay', array( $this, 'page' ) ); add_submenu_page( 'form-relay', 'Submissions', 'Submissions', 'manage_options', 'form-relay-submissions', array( $this, 'submissions_page' ) ); }
	public function assets( $hook ) {
		if ( ! in_array( $hook, array( 'toplevel_page_form-relay', 'form-relay_page_form-relay-submissions' ), true ) ) { return; }
		wp_enqueue_style( 'form-relay-admin', plugins_url( 'css/admin.css', __FILE__ ), array(), FORM_RELAY_VERSION );
		wp_enqueue_script( 'form-relay-admin', plugins_url( 'js/admin.js', __FILE__ ), array(), FORM_RELAY_VERSION, true );
	}
	public function actions() {
		if ( ! current_user_can( 'manage_options' ) || empty( $_POST['form_relay_action'] ) ) { return; }
		check_admin_referer( 'form_relay_admin' ); $action = sanitize_key( wp_unslash( $_POST['form_relay_action'] ) );
		if ( 'save' === $action ) { $this->save(); } elseif ( 'add_form' === $action ) { $this->add_form(); } elseif ( 'duplicate_form' === $action ) { $this->duplicate_form(); } elseif ( 'toggle_form' === $action ) { $this->toggle_form(); } elseif ( 'delete_form' === $action ) { $this->delete_form(); } elseif ( 'test' === $action ) { $this->test(); } elseif ( 'delete_submission' === $action ) { $this->delete_submission(); } elseif ( 'delete_submissions' === $action ) { $this->delete_submissions(); }
	}
	// phpcs:ignore WordPress.Security.NonceVerification.Missing -- This helper is called only after actions() verifies the action nonce.
	private function posted_id() { return sanitize_text_field( isset( $_POST['form_id'] ) ? wp_unslash( $_POST['form_id'] ) : '' ); }
	private function redirect( $id = '', $args = array() ) { if ( $id ) { $args['form_id'] = $id; } wp_safe_redirect( add_query_arg( $args, admin_url( 'admin.php?page=form-relay' ) ) ); exit; }
	private function find_index( $forms, $id ) { foreach ( $forms as $i => $form ) { if ( $form['id'] === $id ) { return $i; } } return false; }
