		$in = isset( $_POST['form'] ) && is_array( $_POST['form'] ) ? wp_unslash( $_POST['form'] ) : array(); $form = $settings['forms'][ $i ];
		$form['name'] = sanitize_text_field( $in['name'] ); $form['enabled'] = empty( $in['enabled'] ) ? 0 : 1; $form['recipient'] = sanitize_email( $in['recipient'] ); $form['from_name'] = sanitize_text_field( $in['from_name'] ); $form['sender_domain'] = $this->sanitize_domain( isset( $in['sender_domain'] ) ? $in['sender_domain'] : '' ); $form['sender_email'] = $this->sanitize_email_local_part( isset( $in['sender_email'] ) ? $in['sender_email'] : '' ); $form['subject'] = sanitize_text_field( $in['subject'] ); $form['reply_to_field'] = sanitize_text_field( $in['reply_to_field'] );
