		$settings['mail']['method'] = $method; $settings['mail']['host'] = sanitize_text_field( isset( $mail_in['host'] ) ? $mail_in['host'] : '' ); $settings['mail']['port'] = max( 1, min( 65535, absint( isset( $mail_in['port'] ) ? $mail_in['port'] : 587 ) ) ); $settings['mail']['encryption'] = isset( $mail_in['encryption'] ) && in_array( $mail_in['encryption'], array( '', 'tls', 'ssl' ), true ) ? $mail_in['encryption'] : 'tls'; $settings['mail']['authentication'] = empty( $mail_in['authentication'] ) ? 0 : 1; $settings['mail']['username'] = sanitize_text_field( isset( $mail_in['username'] ) ? $mail_in['username'] : '' );
