	}
	private function add_form() { $settings = Form_Relay::settings(); $form = Form_Relay::new_form(); $settings['forms'][] = $form; update_option( Form_Relay::OPTION, $settings, false ); $this->redirect( $form['id'], array( 'created' => 1 ) ); }
	private function duplicate_form() { $settings = Form_Relay::settings(); $i = $this->find_index( $settings['forms'], $this->posted_id() ); if ( false === $i ) { $this->redirect(); } $form = $settings['forms'][ $i ]; $form['id'] = Form_Relay::new_form()['id']; $form['name'] .= ' Copy'; $settings['forms'][] = $form; update_option( Form_Relay::OPTION, $settings, false ); $this->redirect( $form['id'], array( 'created' => 1 ) ); }
	// phpcs:ignore WordPress.Security.NonceVerification.Missing -- The action nonce is verified in actions().
	private function toggle_form() { $settings = Form_Relay::settings(); $id = $this->posted_id(); $i = $this->find_index( $settings['forms'], $id ); if ( false !== $i ) { $settings['forms'][ $i ]['enabled'] = empty( $settings['forms'][ $i ]['enabled'] ) ? 1 : 0; update_option( Form_Relay::OPTION, $settings, false ); } if ( ! empty( $_POST['return_to_list'] ) ) { $this->redirect( '', array( 'updated' => 1 ) ); } $this->redirect( $id ); }
	// phpcs:ignore WordPress.Security.NonceVerification.Missing -- The action nonce is verified in actions().
	private function delete_form() { $settings = Form_Relay::settings(); $id = $this->posted_id(); if ( count( $settings['forms'] ) <= 1 ) { set_transient( 'form_relay_notice_' . get_current_user_id(), 'At least one Form must remain.', 60 ); if ( ! empty( $_POST['return_to_list'] ) ) { $this->redirect(); } $this->redirect( $id ); } $settings['forms'] = array_values( array_filter( $settings['forms'], function( $form ) use ( $id ) { return $form['id'] !== $id; } ) ); update_option( Form_Relay::OPTION, $settings, false ); if ( ! empty( $_POST['return_to_list'] ) ) { $this->redirect( '', array( 'deleted' => 1 ) ); } $this->redirect( $settings['forms'][0]['id'], array( 'deleted' => 1 ) ); }
	// phpcs:ignore WordPress.Security.NonceVerification.Missing,WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- The action nonce is verified in actions(); normalise() validates and sanitises decoded field values.
	private function test() { $settings = Form_Relay::settings(); $id = $this->posted_id(); $i = $this->find_index( $settings['forms'], $id ); if ( false === $i ) { $this->redirect(); } $input = json_decode( isset( $_POST['sample_json'] ) ? wp_unslash( $_POST['sample_json'] ) : '', true ); $data = $this->service->normalise( $input ); if ( is_wp_error( $data ) ) { set_transient( 'form_relay_notice_' . get_current_user_id(), $data->get_error_message(), 60 ); $this->redirect( $id ); } $result = $this->service->email( $data, true, $settings['forms'][ $i ] ); set_transient( 'form_relay_notice_' . get_current_user_id(), $result ? 'Test email accepted by the configured mail service.' : 'Test email could not be sent. PHPMailer: ' . $this->service->last_error(), 60 ); $this->redirect( $id ); }
