ss="check"><input type="checkbox" name="form[reset_after_success]" value="1" <?php checked( $form['reset_after_success'] ); ?>> Reset form after successful submission</label><label class="check"><input type="checkbox" name="form[disable_while_submitting]" value="1" <?php checked( $form['disable_while_submitting'] ); ?>> Disable submit button while submitting</label><label class="check"><input type="checkbox" name="form[scroll_to_response]" value="1" <?php checked( $form['scroll_to_response'] ); ?>> Scroll response message into view</label><h2>Spam / Rate Limiting</h2><label>Ignored Fields<textarea name="form[ignored_fields]" rows="6"><?php echo esc_textarea( $form['ignored_fields'] ); ?></textarea><span class="description">One Submitted Field name per line.</span></label><div class="rate"><label>Submissions<input type="number" min="1" name="form[rate_limit]" value="<?php echo esc_attr( $form['rate_limit'] ); ?>"></label><label>Per minutes<input type="number" min="1" name="form[rate_window]" value="<?php echo esc_attr( $form['rate_window'] ); ?>"></label></div></section>
