		?><div class="wrap form-relay form-relay-list form-relay-submissions"><h1 class="wp-heading-inline">Submissions</h1><hr class="wp-header-end"><?php if ( $deleted ) : ?><div class="notice notice-success is-dismissible"><p><?php echo esc_html( 1 === $deleted ? 'Submission deleted.' : $deleted . ' submissions deleted.' ); ?></p></div><?php endif; ?><p>Review form submissions and their email delivery status. Failed deliveries are retained so the submitted message is not lost.</p>
		<form method="get" class="form-relay-filters"><input type="hidden" name="page" value="form-relay-submissions"><select name="form_id"><option value="">All forms</option><?php foreach ( $settings['forms'] as $form ) : ?><option value="<?php echo esc_attr( $form['id'] ); ?>" <?php selected( $form_id, $form['id'] ); ?>><?php echo esc_html( $form['name'] ); ?></option><?php endforeach; ?></select><select name="status"><option value="">All statuses</option><option value="sent" <?php selected( $status, 'sent' ); ?>>Sent</option><option value="failed" <?php selected( $status, 'failed' ); ?>>Failed</option></select><?php submit_button( 'Filter', 'secondary', 'filter_action', false ); ?></form>
		<form method="post"><?php wp_nonce_field( 'form_relay_admin' ); ?><div class="tablenav top"><div class="alignleft actions bulkactions"><button type="submit" class="button confirm-delete" name="form_relay_action" value="delete_submissions">Delete selected</button></div><div class="tablenav-pages"><span class="displaying-num"><?php echo esc_html( number_format_i18n( $result['total'] ) . ( 1 === $result['total'] ? ' item' : ' items' ) ); ?></span><?php $this->submission_pagination( $page, $total_pages, $form_id, $status ); ?></div></div><table class="wp-list-table widefat fixed striped table-view-list submissions"><thead><tr><td class="manage-column column-cb check-column"><input type="checkbox" class="form-relay-select-all"><span class="screen-reader-text">Select all submissions</span></td><th scope="col" class="column-primary">Submission</th><th scope="col">Form</th><th scope="col">Email</th><th scope="col">Status</th><th scope="col">Submitted</th></tr></thead><tbody>
		<?php if ( ! $result['items'] ) : ?><tr class="no-items"><td colspan="6">No submissions found.</td></tr><?php else : foreach ( $result['items'] as $item ) : $fields = $this->decoded( $item['fields'] ); $view_url = add_query_arg( array( 'page' => 'form-relay-submissions', 'submission_id' => $item['id'] ), admin_url( 'admin.php' ) ); $title = $this->submission_title( $fields, $item['id'] ); $email = $this->submission_email( $fields ); ?><tr><th scope="row" class="check-column"><input type="checkbox" name="submission_ids[]" value="<?php echo esc_attr( $item['id'] ); ?>"></th><td class="title column-title has-row-actions column-primary" data-colname="Submission"><strong><a class="row-title" href="<?php echo esc_url( $view_url ); ?>"><?php echo esc_html( $title ); ?></a></strong><div class="row-actions"><span class="view"><a href="<?php echo esc_url( $view_url ); ?>">View</a></span></div><button type="button" class="toggle-row"><span class="screen-reader-text">Show more details</span></button></td><td data-colname="Form"><?php echo esc_html( $item['form_name'] ); ?></td><td data-colname="Email"><?php if ( $email ) : ?><a href="mailto:<?php echo esc_attr( $email ); ?>"><?php echo esc_html( $email ); ?></a><?php else : ?>—<?php endif; ?></td><td data-colname="Status"><span class="form-status form-status--<?php echo esc_attr( 'sent' === $item['status'] ? 'enabled' : 'failed' ); ?>"><?php echo esc_html( 'sent' === $item['status'] ? 'Sent' : 'Failed' ); ?></span></td><td data-colname="Submitted"><?php echo esc_html( mysql2date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $item['created_at'] ) ); ?></td></tr><?php endforeach; endif; ?></tbody><tfoot><tr><td class="manage-column column-cb check-column"><input type="checkbox" class="form-relay-select-all"><span class="screen-reader-text">Select all submissions</span></td><th scope="col" class="column-primary">Submission</th><th scope="col">Form</th><th scope="col">Email</th><th scope="col">Status</th><th scope="col">Submitted</th></tr></tfoot></table><div class="tablenav bottom"><div class="tablenav-pages"><?php $this->submission_pagination( $page, $total_pages, $form_id, $status ); ?></div></div></form></div><?php
	}
	private function submission_detail( $id ) { $item = $this->submissions->get( $id ); if ( ! $item ) { $this->submissions_redirect(); } $fields = $this->decoded( $item['fields'] ); $meta = $this->decoded( $item['meta'] ); ?><div class="wrap form-relay form-relay-submission"><h1 class="wp-heading-inline">Submission #<?php echo esc_html( $item['id'] ); ?></h1> <a class="page-title-action" href="<?php echo esc_url( admin_url( 'admin.php?page=form-relay-submissions' ) ); ?>">All Submissions</a><hr class="wp-header-end"><div class="submission-detail-grid"><section class="relay-card"><h2>Submitted Fields</h2><dl class="submission-fields"><?php foreach ( $fields as $key => $value ) : ?><div><dt><?php echo esc_html( $this->field_label( $key ) ); ?></dt><dd><?php echo nl2br( esc_html( $this->display_value( $value ) ) ); ?></dd></div><?php endforeach; ?></dl></section><aside class="relay-card submission-meta"><h2>Submission Details</h2><dl><dt>Form</dt><dd><?php echo esc_html( $item['form_name'] ); ?></dd><dt>Submitted</dt><dd><?php echo esc_html( mysql2date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $item['created_at'] ) ); ?></dd><dt>Delivery</dt><dd><span class="form-status form-status--<?php echo esc_attr( 'sent' === $item['status'] ? 'enabled' : 'failed' ); ?>"><?php echo esc_html( 'sent' === $item['status'] ? 'Sent' : 'Failed' ); ?></span></dd><dt>Recipient</dt><dd><?php echo esc_html( $item['recipient'] ); ?></dd><dt>Subject</dt><dd><?php echo esc_html( $item['subject'] ); ?></dd><?php if ( ! empty( $meta['page_url'] ) ) : ?><dt>Source</dt><dd><a href="<?php echo esc_url( $meta['page_url'] ); ?>" target="_blank" rel="noopener noreferrer"><?php echo esc_html( ! empty( $meta['page_title'] ) ? $meta['page_title'] : $meta['page_url'] ); ?></a></dd><?php endif; ?><?php if ( $item['error'] ) : ?><dt>Delivery error</dt><dd class="submission-error"><?php echo esc_html( $item['error'] ); ?></dd><?php endif; ?></dl><form method="post"><?php wp_nonce_field( 'form_relay_admin' ); ?><input type="hidden" name="submission_id" value="<?php echo esc_attr( $item['id'] ); ?>"><button class="button button-link-delete confirm-delete" name="form_relay_action" value="delete_submission">Delete Submission</button></form></aside></div></div><?php }
	private function submission_pagination( $current, $total, $form_id, $status ) { if ( $total <= 1 ) { return; } echo wp_kses_post( paginate_links( array( 'base' => add_query_arg( array( 'page' => 'form-relay-submissions', 'form_id' => $form_id, 'status' => $status, 'paged' => '%#%' ), admin_url( 'admin.php' ) ), 'current' => $current, 'total' => $total, 'type' => 'list' ) ) ); }
	private function decoded( $json ) { $value = json_decode( $json, true ); return is_array( $value ) ? $value : array(); }
	private function submission_title( $fields, $id ) { foreach ( array( 'name', 'full_name', 'first_name' ) as $key ) { if ( ! empty( $fields[ $key ] ) && is_scalar( $fields[ $key ] ) ) { return sanitize_text_field( (string) $fields[ $key ] ); } } return 'Submission #' . absint( $id ); }
	private function submission_email( $fields ) { foreach ( $fields as $value ) { if ( is_scalar( $value ) && is_email( (string) $value ) ) { return sanitize_email( (string) $value ); } } return ''; }
	private function field_label( $key ) { return ucwords( str_replace( array( '_', '-' ), ' ', preg_replace( '/([a-z])([A-Z])/', '$1 $2', (string) $key ) ) ); }
	private function display_value( $value ) { if ( is_bool( $value ) ) { return $value ? 'Yes' : 'No'; } if ( is_array( $value ) ) { return implode( ', ', array_map( array( $this, 'display_value' ), $value ) ); } return (string) $value; }
	private function row_action( $form_id, $action, $label, $confirm = false ) { ?><form method="post" class="row-action-form"><?php wp_nonce_field( 'form_relay_admin' ); ?><input type="hidden" name="form_id" value="<?php echo esc_attr( $form_id ); ?>"><input type="hidden" name="return_to_list" value="1"><button type="submit" class="button-link <?php echo $confirm ? 'confirm-delete' : ''; ?>" name="form_relay_action" value="<?php echo esc_attr( $action ); ?>"><?php echo esc_html( $label ); ?></button></form><?php }
	private function response_settings( $form ) { ?><section class="relay-card response-settings"><h2>Responses</h2><div class="response-grid"><div><h3>Error Response</h3><?php $this->field( 'Error Message', 'error_message', $form['error_message'], 'text', 'Supports {{error_message}}, {{error_code}} and {{form_name}}. The message is inserted as the final element inside the form.' ); $this->field( 'Error Message Classes', 'error_classes', $form['error_classes'], 'text', 'Optional space-separated CSS classes added to the error message element.' ); ?></div><div><h3>After a Successful Submission</h3><fieldset class="response-choice"><legend class="screen-reader-text">Thank you response type</legend><label><input type="radio" name="form[response_type]" value="message" <?php checked( $form['response_type'], 'message' ); ?>> Show a Thank You Message</label><label><input type="radio" name="form[response_type]" value="page" <?php checked( $form['response_type'], 'page' ); ?>> Redirect to a Thank You Page</label></fieldset><div data-response-panel="message"><?php $this->field( 'Thank You Message', 'success_message', $form['success_message'], 'text', 'Supports {{form_name}}. The message is inserted as the final element inside the form.' ); $this->field( 'Thank You Message Classes', 'success_classes', $form['success_classes'], 'text', 'Optional space-separated CSS classes added to the thank you message element.' ); ?></div><div data-response-panel="page"><label>Thank You Page<?php wp_dropdown_pages( array( 'name' => 'form[thank_you_page]', 'selected' => absint( $form['thank_you_page'] ), 'show_option_none' => '— Select a page —', 'option_none_value' => '0' ) ); ?><span class="description">Visitors are redirected here after a successful submission.</span></label></div></div></div></section><?php }
	private function mail_settings( $mail ) { ?><section class="relay-card mail-settings"><h2>Email Delivery</h2><p>Choose how Form Relay hands messages to your mail server. This setting applies to every Form on this site.</p><label>Delivery Method<select name="mail[method]" data-mail-method><option value="wordpress" <?php selected( $mail['method'], 'wordpress' ); ?>>WordPress Default</option><option value="local" <?php selected( $mail['method'], 'local' ); ?>>GoDaddy / cPanel Local SMTP</option><option value="custom" <?php selected( $mail['method'], 'custom' ); ?>>Custom SMTP</option></select><span class="description">WordPress Default respects your host and any installed SMTP plugin. Existing Form Relay installations continue using the local cPanel relay.</span></label><div class="mail-method-note" data-mail-panel="local"><strong>Local SMTP settings</strong><p>Connects to <code>127.0.0.1:25</code> without authentication. Choose this for compatible GoDaddy or cPanel hosting.</p></div><div class="smtp-fields" data-mail-panel="custom"><div class="smtp-grid"><label>SMTP Host<input type="text" name="mail[host]" value="<?php echo esc_attr( $mail['host'] ); ?>" placeholder="smtp.example.com"></label><label>Port<input type="number" min="1" max="65535" name="mail[port]" value="<?php echo esc_attr( $mail['port'] ); ?>"></label><label>Encryption<select name="mail[encryption]"><option value="" <?php selected( $mail['encryption'], '' ); ?>>None</option><option value="tls" <?php selected( $mail['encryption'], 'tls' ); ?>>TLS</option><option value="ssl" <?php selected( $mail['encryption'], 'ssl' ); ?>>SSL</option></select></label></div><label class="check"><input type="checkbox" name="mail[authentication]" value="1" <?php checked( $mail['authentication'] ); ?> data-smtp-auth> SMTP server requires authentication</label><div class="smtp-auth-fields"><label>SMTP Username<input type="text" name="mail[username]" value="<?php echo esc_attr( $mail['username'] ); ?>" autocomplete="off"></label><label>SMTP Password<input type="password" name="mail[password]" value="" autocomplete="new-password" placeholder="<?php echo empty( $mail['password'] ) ? 'Not configured' : 'Saved — leave blank to keep'; ?>"><span class="description">For better security, define <code>FORM_RELAY_SMTP_PASSWORD</code> in <code>wp-config.php</code> instead of saving a password here.</span></label><?php if ( ! empty( $mail['password'] ) ) : ?><label class="check"><input type="checkbox" name="mail[clear_password]" value="1"> Remove the saved SMTP password</label><?php endif; ?></div></div></section><?php }
	private function sanitize_classes( $classes ) { return implode( ' ', array_values( array_filter( array_map( 'sanitize_html_class', preg_split( '/\s+/', (string) $classes ) ) ) ) ); }
	private function sanitize_domain( $domain ) {
		$domain = strtolower( trim( sanitize_text_field( $domain ) ) );
		$domain = preg_replace( '#^https?://#', '', $domain );
		$domain = preg_replace( '#/.*$#', '', $domain );
		return preg_replace( '/[^a-z0-9.-]/', '', preg_replace( '/^www\./', '', $domain ) );
	}
	private function sanitize_email_local_part( $local ) { return preg_replace( "/[^a-z0-9.!#$%&'*+\/=?^_`{|}~-]/i", '', sanitize_text_field( $local ) ); }
	private function sender_email_field( $form ) { ?><label>Sender Email<span class="sender-email"><input type="text" name="form[sender_email]" value="<?php echo esc_attr( $form['sender_email'] ); ?>" aria-describedby="form-relay-sender-email-help"><span class="sender-email__domain">@<?php echo esc_html( $form['sender_domain'] ); ?></span></span><span class="description" id="form-relay-sender-email-help">Enter only the part before the @. The complete sender address must exist on your mail server.</span></label><?php }
	private function preview_modal() { ?><div id="form-relay-preview-modal" class="form-relay-modal" data-site-name="<?php echo esc_attr( get_bloginfo( 'name' ) ); ?>" hidden><div class="form-relay-modal__backdrop" data-preview-close></div><section class="form-relay-modal__dialog" role="dialog" aria-modal="true" aria-labelledby="form-relay-preview-title"><header><div><h2 id="form-relay-preview-title">Email Preview</h2><p class="description">Rendered with generic dummy submission data. Nothing will be sent.</p></div><button type="button" class="button-link form-relay-modal__close" data-preview-close aria-label="Close preview"><span class="dashicons dashicons-no-alt" aria-hidden="true"></span></button></header><div class="form-relay-modal__status"><span class="spinner is-active"></span> Rendering preview…</div><div class="form-relay-modal__error" role="alert" hidden><p></p></div><iframe class="form-relay-modal__frame" title="Rendered email preview" hidden></iframe><footer><button type="button" class="button" data-preview-close>Close</button></footer></section></div><?php }
	private function field( $label, $key, $value, $type = 'text', $help = '' ) { ?><label><?php echo esc_html( $label ); ?><input type="<?php echo esc_attr( $type ); ?>" name="form[<?php echo esc_attr( $key ); ?>]" value="<?php echo esc_attr( $value ); ?>"><?php if ( $help ) : ?><span class="description"><?php echo esc_html( $help ); ?></span><?php endif; ?></label><?php }
	private function insert_buttons( $items, $target ) { ?><div class="quick-insert" data-target="<?php echo esc_attr( $target ); ?>"><?php foreach ( $items as $placeholder => $label ) : ?><button type="button" class="button button-small" data-placeholder="{{<?php echo esc_attr( $placeholder ); ?>}}"><?php echo esc_html( $label ); ?></button><?php endforeach; ?></div><?php }
	private function reference() { ?><section class="relay-card reference"><h2>Template Placeholder Reference</h2><div class="reference-grid"><div><h3>Main Email Template</h3><dl><dt><code>{{form_name}}</code></dt><dd>The configured name of this Form.</dd><dt><code>{{site_name}}</code></dt><dd>The website name supplied in metadata.</dd><dt><code>{{page_title}}</code></dt><dd>The title of the page containing the Form.</dd><dt><code>{{page_url}}</code></dt><dd>The URL of the page containing the Form.</dd><dt><code>{{submitted_at}}</code></dt><dd>The formatted submission date and time.</dd><dt><code>{{fields}}</code></dt><dd>The concatenated output of the Field Row Template, repeated for every Submitted Field that is not ignored or internal. It is not a single value.</dd></dl><h4>What {{fields}} produces</h4><p>For Submitted Fields <code>name</code>, <code>email</code>, <code>service</code>, and <code>message</code>, this row:</p><pre>&lt;tr&gt;
  &lt;td&gt;&lt;strong&gt;{{field_label}}&lt;/strong&gt;&lt;/td&gt;
  &lt;td&gt;{{field_value}}&lt;/td&gt;
&lt;/tr&gt;</pre><p>is repeated four times, producing rows for Name/Sample User, Email/sample@example.com, Service/Web Development, and Message/I’d like to discuss a new website. The combined HTML replaces <code>{{fields}}</code> in the Main Email Template.</p></div><div><h3>Field Row Template</h3><dl><dt><code>{{field_key}}</code></dt><dd>Original HTML Submitted Field name, such as <code>first_name</code>.</dd><dt><code>{{field_label}}</code></dt><dd>Automatically generated readable label; <code>first_name</code> becomes “First Name”.</dd><dt><code>{{field_value}}</code></dt><dd>Sanitised and formatted Submitted Field value, such as “Sample User”.</dd></dl><h3>Rendering flow</h3><pre>&lt;form data-form-relay="f_DEMO01"&gt;
  &lt;input name="name"&gt;
  &lt;input name="email"&gt;
  &lt;select name="service"&gt;...&lt;/select&gt;
  &lt;textarea name="message"&gt;&lt;/textarea&gt;
&lt;/form&gt;</pre><p>The Field Row Template is repeated for Name, Email, Service and Message. That generated HTML replaces <code>{{fields}}</code> in the Main Email Template.</p></div></div></section><?php }
	private function message_reference() { ?><section class="relay-card reference"><h2>Success and Error Message Placeholders</h2><div class="reference-grid"><div><h3>Success and Error Messages</h3><dl><dt><code>{{form_name}}</code></dt><dd>The configured Form name. Available in both Success and Error Messages.</dd><dt><code>{{error_message}}</code></dt><dd>A friendly, public-facing description of the submission error. Available only in Error Messages. Internal mail or server details are never inserted.</dd><dt><code>{{error_code}}</code></dt><dd>A predictable machine-readable identifier such as <code>mail_failed</code> or <code>rate_limited</code>. Available only in Error Messages.</dd></dl></div><div><h3>Example Error Message</h3><pre>Sorry, we couldn't process your submission. {{error_message}}</pre><p>For a temporary delivery failure, this might render as:</p><pre>Sorry, we couldn't process your submission. We couldn't send your message right now.</pre><p>Developer filters <code>form_relay_error_code</code> and <code>form_relay_error_message</code> can customise public-safe errors.</p></div></div></section><?php }
}
